except a.ABIValueError: print('arg type ok')

for bad in [3, '0xzz', '0xf0f']:
    try: a.decode_contract_call(r, bad)
    except a.AbiContractCallError as e: print('data invalid:', e.code)

for bad in ['', 'g', 'receive', 'fallback', 5]:
    try: a.encode_contract_call(r, bad)
    except a.AbiContractCallError as e: print('target:', repr(bad), e.code)

r2 = a.parse_contract_call_registry(fn_only + [{'type':'receive'},{'type':'fallback'}])
try: a.encode_contract_call(r2,'receive',[1])
except a.AbiContractCallError as e: print('recv args:', e.code)
try: a.encode_contract_call(r2,'receive',data=b'\x00')
except a.AbiContractCallError as e: print('recv data:', e.code)
try: a.encode_contract_call(r2,'receive',data='0xzz')
except a.AbiContractCallError as e: print('recv hex:', e.code)
try: a.encode_contract_call(r2,'fallback',[1])
except a.AbiContractCallError as e: print('fb args:', e.code)
try: a.encode_contract_call(r2,'f',data=b'')
except a.AbiContractCallError as e: print('fn data:', e.code)

